def count_valid_grids(n, k):
    MOD = 10**9 + 7

    if n > k:
        return 0

    def binomial_coefficient(n, k):
        if k > n:
            return 0
        if k == 0 or k == n:
            return 1

        C = [0] * (k + 1)
        C[0] = 1

        for i in range(1, n + 1):
            j = min(i, k)
            while j > 0:
                C[j] = (C[j] + C[j - 1]) % MOD
                j -= 1

        return C[k]

    result = 0
    for i in range(1, k - n + 2):
        result = (result + binomial_coefficient(k - i, n - 1)) % MOD

    return result

