def count_ways_to_fill_grid(n, k):
    MOD = 10**9 + 7

    # Calculate factorial modulo MOD
    fact = [1] * (2 * n)
    for i in range(2, 2 * n):
        fact[i] = fact[i - 1] * i % MOD

    # Calculate modular inverse using Fermat's Little Theorem
    def mod_inverse(a, m):
        return pow(a, m - 2, m)

    # Calculate combinations nCr % MOD
    def comb(n, r):
        if r > n:
            return 0
        return fact[n] * mod_inverse(fact[r], MOD) % MOD * mod_inverse(fact[n - r], MOD) % MOD

    # Calculate the number of ways
    result = comb(2 * n - 2, n - 1)
    result = (result * k) % MOD
    return result

