def factorial_mod(n, mod):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % mod
    return result

def count_ways(n, k):
    # Number of ways to choose n numbers from k options, considering repetitions
    return factorial_mod(k + n - 1, MOD) * pow(factorial_mod(n - 1, MOD) * factorial_mod(k, MOD), MOD - 2, MOD) % MOD

