def count_grid_arrangements(n, k):
    def mod_inverse(a, m):
        def extended_gcd(a, b):
            if a == 0:
                return b, 0, 1
            else:
                gcd, x, y = extended_gcd(b % a, a)
                return gcd, y - (b // a) * x, x

        gcd, x, _ = extended_gcd(a, m)
        if gcd != 1:
            raise ValueError("Modular inverse does not exist")
        else:
            return x % m

    def nCr(n, r):
        if r > n:
            return 0
        r = min(r, n - r)
        numerator = 1
        denominator = 1
        for i in range(r):
            numerator = (numerator * (n - i)) % MOD
            denominator = (denominator * (i + 1)) % MOD
        return (numerator * mod_inverse(denominator, MOD)) % MOD

    result = 0
    for first_row in range(1, k + 1):
        ways = nCr(k - first_row, n - 1)
        ways = (ways * pow(first_row, n - 1, MOD)) % MOD
        result = (result + ways) % MOD

    return result

