def count_ways(n, k):
    MOD = 10**9 + 7

    if n > k:
        return 0

    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = (dp[i][j - 1] + dp[i - 1][j] - dp[i - 1][j - 1]) % MOD
            if j > i:
                dp[i][j] = (dp[i][j] + MOD - dp[i - 1][j - i]) % MOD

    result = dp[n][k]
    for i in range(n + 1, k + 1):
        result = (result * i) % MOD

    return result

n, k = map(int, input().split())
